import re
from pathlib import Path

from ci.praktika.info import Info
from ci.praktika.utils import Shell

FILE_WITH_VERSION_PATH = "./cmake/autogenerated_versions.txt"

# Canonical layout of cmake/autogenerated_versions.txt as committed to the repo.
VERSIONS_TEMPLATE = """\
# This variables autochanged by ci/jobs/create_release.py:

# NOTE: VERSION_REVISION has nothing common with DBMS_TCP_PROTOCOL_VERSION,
# only DBMS_TCP_PROTOCOL_VERSION should be incremented on protocol changes.
SET(VERSION_REVISION {revision})
SET(VERSION_MAJOR {major})
SET(VERSION_MINOR {minor})
SET(VERSION_PATCH {patch})
SET(VERSION_GITHASH {githash})
SET(VERSION_DESCRIBE {describe})
SET(VERSION_STRING {string})
# end of autochange
"""


class VersionType:
    NEW = "new"
    TESTING = "testing"
    PRESTABLE = "prestable"
    STABLE = "stable"
    LTS = "lts"
    VALID = {NEW, TESTING, PRESTABLE, STABLE, LTS}


def _read_versions() -> dict:
    versions = {}
    for line in Path(FILE_WITH_VERSION_PATH).read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line.startswith("SET("):
            continue
        name, value = line[4:-1].split(maxsplit=1)
        name = name.removeprefix("VERSION_").lower()
        try:
            value = int(value)
        except ValueError:
            pass
        versions[name] = value
    return versions


def _write_version_file(version_dict: dict) -> None:
    Path(FILE_WITH_VERSION_PATH).write_text(
        VERSIONS_TEMPLATE.format_map(version_dict), encoding="utf-8"
    )


def _tweak_from_git(githash) -> int:
    """The tweak: the commit count since `githash` on the first-parent history
    (`git rev-list --count`). It does not use tags, so tags need not be fetched.
    Falls back to 1 on a shallow checkout or any git error."""
    try:
        return int(
            Shell.get_output(
                f"git rev-list --count --first-parent {githash}..HEAD",
                verbose=True,
            )
        )
    except (ValueError, Exception):
        return 1


class CHVersion:
    """The ClickHouse release version.

    A stateful model (`major.minor.patch.tweak`, plus `revision` and
    `version_type`) that the release process reads, bumps and writes. The CI
    build path stamps the binary version through the `*_as_dict` /
    `set_binary_version` helpers, which additionally consult the CI `Info`
    context; the stateful model deliberately does not, so it is safe inside a
    checkout of an arbitrary release commit.
    """

    def __init__(self, major, minor, patch, revision, tweak=1):
        self.major = int(major)
        self.minor = int(minor)
        self.patch = int(patch)
        self.revision = int(revision)
        self.tweak = int(tweak)
        self.version_type = ""

    # --- reading / writing the version model ---------------------------------

    @classmethod
    def read(cls, with_tweak: bool = True) -> "CHVersion":
        """Read the version from `cmake/autogenerated_versions.txt`. With
        `with_tweak`, the tweak is the commit count since the file's githash (git
        history, no tags); otherwise it stays 1. Consults neither the CI `Info`
        context nor `_Environment`, so it is safe inside a checkout of an
        arbitrary release commit."""
        versions = _read_versions()
        version = cls(
            versions["major"],
            versions["minor"],
            versions["patch"],
            versions["revision"],
        )
        if with_tweak:
            version.tweak = _tweak_from_git(versions["githash"])
        return version

    def write(self, preserve_sha: bool = False) -> None:
        """Write this version to `cmake/autogenerated_versions.txt`. With
        `preserve_sha`, the file's existing githash is kept (the post-release
        bump on `master` must not repoint the githash at the release commit)."""
        version_dict = self.to_json()
        if preserve_sha:
            version_dict["githash"] = _read_versions().get("githash", "0" * 40)
        _write_version_file(version_dict)

    def to_json(self) -> dict:
        return {
            "revision": self.revision,
            "major": self.major,
            "minor": self.minor,
            "patch": self.patch,
            "tweak": self.tweak,
            "githash": Shell.get_output("git rev-parse HEAD") or "0" * 40,
            "describe": self.describe,
            "string": self.string,
        }

    # --- bumping -------------------------------------------------------------

    def bump_release(self) -> "CHVersion":
        """Bump the minor version (or wrap to the next major when minor reaches 12)."""
        if self.minor < 12:
            self.minor += 1
        else:
            self.major += 1
            self.minor = 1
        self.revision += 1
        self.patch = 1
        self.tweak = 1
        return self

    def bump_patch(self) -> "CHVersion":
        self.revision += 1
        self.patch += 1
        self.tweak = 1
        return self

    # --- comparison / rendering ----------------------------------------------

    def with_description(self, version_type: str) -> "CHVersion":
        if version_type not in VersionType.VALID:
            raise ValueError(f"version type {version_type!r} not in {VersionType.VALID}")
        self.version_type = version_type
        return self

    def get_stable_release_type(self) -> str:
        return VersionType.LTS if self.minor % 5 == 3 else VersionType.STABLE

    def is_older(self, other: "CHVersion") -> bool:
        """Whether this is an older release than `other`, by release triple
        (major, minor, patch). The tweak is a within-patch commit count and does
        not define a newer release."""
        return (self.major, self.minor, self.patch) < (
            other.major,
            other.minor,
            other.patch,
        )

    def is_newer(self, other: "CHVersion") -> bool:
        return other.is_older(self)

    @property
    def string(self) -> str:
        return f"{self.major}.{self.minor}.{self.patch}.{self.tweak}"

    @property
    def describe(self) -> str:
        return f"v{self.string}-{self.version_type}" if self.version_type else ""

    # --- CI build version stamping (uses the CI Info context) ----------------

    @classmethod
    def get_release_version_as_dict(cls) -> dict:
        versions = _read_versions()
        return {
            key: versions[key]
            for key in (
                "major",
                "minor",
                "patch",
                "revision",
                "githash",
                "describe",
                "string",
            )
        }

    @classmethod
    def get_current_version_as_dict(cls):
        """Version stamped into the binary during a CI build.

        In a PR the tweak is pinned to 1 and git history is NOT consulted: the
        merge commit's count diverges across close/reopen for the same HEAD,
        which would upload diverging version strings to one artifact prefix. On
        master / release branches the tweak is the real commit count and the type
        is derived from the branch. githash is always the CI sha.
        """
        info = Info()
        version = cls.get_release_version_as_dict()
        version_type = "testing"
        if info.pr_number != 0:
            version["tweak"] = 1
        else:
            version["tweak"] = _tweak_from_git(version["githash"])
            if bool(
                re.match(r"^\d{2}\.\d+$", info.git_branch.removeprefix("release/"))
            ):
                version_type = "lts" if version["minor"] % 5 == 3 else "stable"
        version["string"] = (
            f'{version["major"]}.{version["minor"]}.{version["patch"]}.{version["tweak"]}'
        )
        version["githash"] = info.sha
        version["describe"] = f'v{version["string"]}-{version_type}'
        return version

    @classmethod
    def set_binary_version(cls, version_dict=None):
        _write_version_file(version_dict or cls.get_current_version_as_dict())

    @staticmethod
    def store_version_data_in_ci_pipeline(version):
        print(f"Store version in pipeline kv data: [version={version}]")
        Info().store_kv_data("version", version)


if __name__ == "__main__":
    # test;
    print(CHVersion.get_current_version_as_dict())
